export type MaskPreset = { label: string; src: string; mode: "luminance" | "alpha"; group: string };

const _s = (inner: string): string => {
  const full = `<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'>${inner}</svg>`;
  return "data:image/svg+xml," + encodeURIComponent(full);
};

const _lg = (id: string, x1: number, y1: number, x2: number, y2: number, stops: string) =>
  `<linearGradient id='${id}' x1='${x1}' y1='${y1}' x2='${x2}' y2='${y2}'>${stops}</linearGradient>`;
const _rg = (id: string, cx: number, cy: number, r: number, stops: string) =>
  `<radialGradient id='${id}' cx='${cx}%' cy='${cy}%' r='${r}%'>${stops}</radialGradient>`;
const _wb = `<stop offset='0' stop-color='white'/><stop offset='1' stop-color='black'/>`;
const _bw = `<stop offset='0' stop-color='black'/><stop offset='1' stop-color='white'/>`;

const _poly = (n: number, cx: number, cy: number, r: number, startDeg = -90): string =>
  Array.from({ length: n }, (_, i) => {
    const a = ((startDeg + (360 / n) * i) * Math.PI) / 180;
    return `${(cx + r * Math.cos(a)).toFixed(1)},${(cy + r * Math.sin(a)).toFixed(1)}`;
  }).join(" ");

const _star = (n: number, cx: number, cy: number, ro: number, ri: number): string =>
  Array.from({ length: n * 2 }, (_, i) => {
    const a = ((i * 180) / n - 90) * (Math.PI / 180);
    const r = i % 2 === 0 ? ro : ri;
    return `${(cx + r * Math.cos(a)).toFixed(1)},${(cy + r * Math.sin(a)).toFixed(1)}`;
  }).join(" ");

